1	using System.Diagnostics.CodeAnalysis;
2	using System.Text.Json.Serialization;
3	using Intropy.Topology.Validation;
4	
5	namespace Intropy.Topology;
6	
7	/// <summary>
8	/// Reference to a pub/sub topic: a Dapr pubsub component name plus a topic name.
9	/// Topics are declared as static fields — in a scaffolded <c>Topics.cs</c> for
10	/// system-internal topics, or in a shared contracts package for cross-system topics;
11	/// the declaration site is the visibility marker. The backing pubsub resource
12	/// materializes from usage; there is no <c>AddTopic</c> on the builder.
13	/// </summary>
14	public abstract record TopicRef
15	{
16	    /// <summary>The Dapr pubsub component name (DNS-1123 subdomain).</summary>
17	    public string PubSubName { get; }
18	
19	    /// <summary>The topic name within the pubsub (DNS-1123 subdomain).</summary>
20	    public string TopicName { get; }
21	
22	    /// <summary>The event contract type carried on the topic.</summary>
23	    public abstract Type ContractType { get; }
24	
25	    private protected TopicRef(string pubSubName, string topicName)
26	    {
27	        PubSubName = NameRules.RequireSubdomain(pubSubName, nameof(pubSubName));
28	        TopicName = NameRules.RequireSubdomain(topicName, nameof(topicName));
29	    }
30	}
31	
32	/// <summary>
33	/// A <see cref="TopicRef"/> typed with its event contract <typeparamref name="T"/>.
34	/// The type parameter documents the contract at the declaration site and lets future
35	/// generation/codegen reflect on it; topology-level wiring only uses the names.
36	/// </summary>
37	/// <typeparam name="T">The event contract type published on the topic.</typeparam>
38	public sealed record TopicRef<T> : TopicRef
39	{
40	    /// <inheritdoc />
41	    public override Type ContractType => typeof(T);
42	
43	    private TopicRef(string pubSubName, string topicName)
44	        : base(pubSubName, topicName)
45	    {
46	    }
47	
48	    /// <summary>Declares a topic on a pubsub component.</summary>
49	    /// <param name="pubSubName">The Dapr pubsub component name (DNS-1123 subdomain).</param>
50	    /// <param name="topicName">The topic name (DNS-1123 subdomain).</param>
51	    /// <exception cref="ArgumentException">A name is not a valid DNS-1123 subdomain.</exception>
52	    public static TopicRef<T> Define(
53	        [ConstantExpected] string pubSubName,
54	        [ConstantExpected] string topicName) =>
55	        new(pubSubName, topicName);
56	}
