58	/// <summary>
59	/// A connector — the named connection point between the system and the outside world.
60	/// Every edge block reaches the outside world through a connector. Its transport selects
61	/// the Dapr binding type it materializes as; the Dapr binding component's name is always
62	/// derived (<c>binding.&lt;connector-name&gt;</c>), never declared. Connectors are declared
63	/// in the SystemHost (typically a scaffolded <c>Connectors.cs</c>); they are system-owned and
64	/// never shared across systems. Direction is not part of the identity — it follows from
65	/// usage (<c>From</c> / <c>To</c>).
66	/// </summary>
67	public sealed record ConnectorRef
68	{
69	    /// <summary>The connector's name (DNS-1123 label, e.g. <c>pim</c>).</summary>
70	    public string Name { get; }
71	
72	    /// <summary>The transport — the kind of Dapr binding the connector materializes as.</summary>
73	    public Transport Transport { get; }
74	
75	    private ConnectorRef(string name, Transport transport)
76	    {
77	        Name = name;
78	        Transport = transport;
79	    }
80	
81	    /// <summary>
82	    /// Declares a connector resolved to a transport — the form <c>intropy system create</c>
83	    /// emits for the default local-file resolution, where the transport's endpoint (e.g. a
84	    /// <see cref="FileTransport"/> folder) is the connection itself.
85	    /// </summary>
86	    /// <param name="name">The connector's name (DNS-1123 label).</param>
87	    /// <param name="transport">The kind of Dapr binding the connector materializes as.</param>
88	    /// <exception cref="ArgumentException">The name is not a valid DNS-1123 label.</exception>
89	    public static ConnectorRef Define([ConstantExpected] string name, Transport transport)
90	    {
91	        ArgumentNullException.ThrowIfNull(transport);
92	        return new ConnectorRef(NameRules.RequireLabel(name, nameof(name)), transport);
93	    }
94	}
95	
96	/// <summary>
97	/// The kind of Dapr binding a connector materializes as. All connectivity goes through
98	/// Dapr — the transport selects the Dapr binding component's <c>spec.type</c>; it never
99	/// bypasses Dapr. The component name is always derived: <c>binding.&lt;connector-name&gt;</c>.
100	/// </summary>
101	[JsonPolymorphic(TypeDiscriminatorPropertyName = "$transport")]
102	[JsonDerivedType(typeof(FileTransport), "file")]
103	public abstract record Transport
104	{
105	    private protected Transport()
106	    {
107	    }
108	
109	    /// <summary>The Dapr binding component's <c>spec.type</c> (e.g. <c>bindings.localstorage</c>).</summary>
110	    public abstract string DaprType { get; }
111	
112	    /// <summary>
113	    /// Local file transport (<c>bindings.localstorage</c>): reads and writes files in a folder on
114	    /// the host. The folder is the endpoint. This is the default resolution
115	    /// <c>intropy system create</c> applies.
116	    /// </summary>
117	    /// <param name="rootPath">The folder the binding reads and writes, relative to the SystemHost directory or absolute.</param>
118	    /// <exception cref="ArgumentException">The root path is null or whitespace.</exception>
119	    public static Transport File([ConstantExpected] string rootPath) => new FileTransport(rootPath);
120	}
121	
122	/// <summary>
123	/// Local file transport: a Dapr binding component of type <c>bindings.localstorage</c> rooted at
124	/// <see cref="RootPath"/>. The folder is the endpoint.
125	/// </summary>
126	public sealed record FileTransport : Transport
127	{
128	    /// <inheritdoc />
129	    public override string DaprType => "bindings.localstorage";
130	
131	    /// <summary>The folder the binding reads and writes, relative to the SystemHost directory or absolute.</summary>
132	    public string RootPath { get; }
133	
134	    /// <summary>Creates a local file transport. Prefer <see cref="Transport.File"/>.</summary>
135	    /// <param name="rootPath">The folder the binding reads and writes.</param>
136	    /// <exception cref="ArgumentException">The root path is null or whitespace.</exception>
137	    public FileTransport(string rootPath)
138	    {
139	        ArgumentException.ThrowIfNullOrWhiteSpace(rootPath);
140	        RootPath = rootPath;
141	    }
142	}
