1	using Intropy.Topology.Building;
2	using Intropy.Topology.Model;
3	using Intropy.Topology.Validation;
4	
5	namespace Intropy.Topology;
6	
7	/// <summary>
8	/// Entry point for declaring an integration system's topology. Add components, wire
9	/// them to topics and connectors, then call <see cref="Build"/> to materialize and
10	/// validate the immutable <see cref="SystemTopology"/>. Resources (topics, connectors)
11	/// materialize from usage — there is no <c>AddTopic</c>. Not thread-safe;
12	/// a second <see cref="Build"/> after further mutation reflects the mutations.
13	/// </summary>
14	public sealed class SystemBuilder
15	{
16	    private readonly List<Component> _components = [];
17	
18	    /// <summary>The system's name (DNS-1123 label).</summary>
19	    public string SystemName { get; }
20	
21	    private SystemBuilder(string systemName)
22	    {
23	        SystemName = systemName;
24	    }
25	
26	    internal IReadOnlyList<Component> Components => _components;
27	
28	    /// <summary>Creates a builder for a named system.</summary>
29	    /// <param name="systemName">The system's name (DNS-1123 label).</param>
30	    /// <exception cref="ArgumentException">The name is not a valid DNS-1123 label.</exception>
31	    public static SystemBuilder Create(string systemName) =>
32	        new(NameRules.RequireLabel(systemName, nameof(systemName)));
33	
34	    /// <summary>Adds an extractor: pulls data out of an external system and publishes it.</summary>
35	    /// <param name="name">The component's name (DNS-1123 label).</param>
36	    public ExtractorBuilder AddExtractor(string name) =>
37	        new(Register(new ExtractorComponent(NameRules.RequireLabel(name, nameof(name)))));
38	
39	    /// <summary>Adds a loader: consumes a topic and writes to an external system.</summary>
40	    /// <param name="name">The component's name (DNS-1123 label).</param>
41	    public LoaderBuilder AddLoader(string name) =>
42	        new(Register(new LoaderComponent(NameRules.RequireLabel(name, nameof(name)))));
43	
44	    /// <summary>Adds a transactional integration.</summary>
45	    /// <param name="name">The component's name (DNS-1123 label).</param>
46	    public TransactionalIntegrationBuilder AddTransactionalIntegration(string name) =>
47	        new(Register(new TransactionalIntegrationComponent(NameRules.RequireLabel(name, nameof(name)))));
48	
49	    /// <summary>
50	    /// Materializes and validates the topology. Throws when any error-severity
51	    /// violation exists, carrying every diagnostic found.
52	    /// </summary>
53	    /// <exception cref="TopologyValidationException">The declared topology is invalid.</exception>
54	    public SystemTopology Build() =>
55	        TryBuild(out var topology, out var diagnostics)
56	            ? topology!
57	            : throw new TopologyValidationException(diagnostics);
58	
59	    /// <summary>Non-throwing <see cref="Build"/>: returns false with the diagnostics when the topology is invalid.</summary>
60	    /// <param name="topology">The topology when valid; null otherwise.</param>
61	    /// <param name="diagnostics">All diagnostics found, including warnings.</param>
62	    public bool TryBuild(out SystemTopology? topology, out IReadOnlyList<TopologyDiagnostic> diagnostics)
63	    {
64	        var candidate = TopologyMaterializer.Materialize(this);
65	        diagnostics = TopologyRules.Run(this, candidate);
66	        if (diagnostics.Any(d => d.Severity == DiagnosticSeverity.Error))
67	        {
68	            topology = null;
69	            return false;
70	        }
71	
72	        topology = candidate;
73	        return true;
74	    }
75	
76	    /// <summary>Runs validation without throwing; returns all diagnostics including warnings.</summary>
77	    public IReadOnlyList<TopologyDiagnostic> Validate() =>
78	        TopologyRules.Run(this, TopologyMaterializer.Materialize(this));
79	
80	    private T Register<T>(T component) where T : Component
81	    {
82	        _components.Add(component);
83	        return component;
84	    }
85	}
