1	using System.Reflection;
2	using Aspire.Hosting;
3	using Aspire.Hosting.ApplicationModel;
4	using CommunityToolkit.Aspire.Hosting.Dapr;
5	using Intropy.Topology.Generation;
6	using Intropy.Topology.Model;
7	using Microsoft.Extensions.DependencyInjection;
8	using Microsoft.Extensions.DependencyInjection.Extensions;
9	
10	namespace Intropy.Topology.Aspire;
11	
12	/// <summary>
13	/// The Aspire run-backend. Discovers a system's validated topology, generates its Dapr
14	/// components, and translates the model into Aspire resources — one project per component
15	/// with a Dapr sidecar on its own staged component overlay, and RabbitMQ behind pub/sub —
16	/// then runs it under DCP, subscribers before their publishers. Scheduled components are
17	/// re-run on their cron ticks by the <see cref="ComponentScheduler"/> (CronJob emulation,
18	/// with a "Run now" dashboard command). Aspire never sees the topology; it receives
19	/// ordinary resources.
20	/// </summary>
21	public static class IntropyAspire
22	{
23	    /// <summary>Fixed host port for the local RabbitMQ backend (generated pub/sub YAML points here).</summary>
24	    internal const int RabbitMqPort = 5672;
25	
26	    /// <summary>
27	    /// Discovers the system in <paramref name="assembly"/>, generates its artifacts to a temp folder,
28	    /// builds the Aspire resource graph, and runs it. Requires Docker and the Dapr CLI to be present.
29	    /// </summary>
30	    /// <param name="assembly">The assembly declaring the <see cref="ISystemDefinition"/>.</param>
31	    /// <param name="args">Command-line args passed through to the distributed application builder.</param>
32	    /// <returns>A process exit code.</returns>
33	    public static async Task<int> RunAsync(Assembly assembly, string[] args)
34	    {
35	        ArgumentNullException.ThrowIfNull(assembly);
36	        ArgumentNullException.ThrowIfNull(args);
37	
38	        var discovered = SystemDiscovery.Discover(assembly);
39	
40	        var generatedRoot = Path.Combine(
41	            Path.GetTempPath(), "intropy-aspire", $"{discovered.Topology.SystemName}-{Guid.NewGuid():N}");
42	        TopologyGenerator.Generate(discovered.Topology).WriteTo(generatedRoot);
43	
44	        var builder = DistributedApplication.CreateBuilder(args);
45	        Apply(builder, discovered.Topology, generatedRoot);
46	
47	        var app = builder.Build();
48	        await app.RunAsync().ConfigureAwait(false);
49	        return 0;
50	    }
51	
52	    /// <summary>
53	    /// Translates the topology into Aspire resources on <paramref name="builder"/>. Separated from
54	    /// <see cref="RunAsync"/> so the built model can be inspected in tests without running DCP.
55	    /// </summary>
56	    internal static void Apply(
57	        IDistributedApplicationBuilder builder, SystemTopology topology, string generatedRoot)
58	    {
59	        var componentsPath = Path.Combine(generatedRoot, GeneratedArtifacts.ComponentsDir);
60	        var configDir = Path.Combine(generatedRoot, GeneratedArtifacts.ConfigDir);
61	
62	        // A plain RabbitMQ container rather than AddRabbitMQ: the generated pub/sub YAML speaks
63	        // default guest/guest to localhost:5672, while AddRabbitMQ injects generated credentials.
64	        var rabbitmq = builder
65	            .AddContainer("rabbitmq", "docker.io/library/rabbitmq", "4")
66	            .WithEndpoint(port: RabbitMqPort, targetPort: RabbitMqPort);
67	        WithTcpReadiness(builder, rabbitmq, RabbitMqPort);
68	
69	        // Everything a sidecar dials during component init. Sidecars must wait for these to be
70	        // *ready* (not merely running) — daprd treats a failed component init as fatal, so racing
71	        // a still-starting backend kills the sidecar.
72	        var backends = new List<IResourceBuilder<IResource>> { rabbitmq };
73	        var backendProbes = new List<TcpReadyHealthCheck> { new("localhost", RabbitMqPort) };
74	
75	        // Filled after the component loop; the hook closure only reads it at runtime.
76	        var sidecarWaits = new Dictionary<string, string[]>(StringComparer.Ordinal);
77	
78	        // The Dapr toolkit materializes each sidecar as a separate "<component>-dapr-cli" executable
79	        // that does not carry wait annotations, so WaitFor cannot gate it. Hold its start here until
80	        // every backend port answers and, for publishers, until every subscriber sidecar is running.
81	        builder.Eventing.Subscribe<BeforeResourceStartedEvent>(async (evt, cancellationToken) =>
82	        {
83	            if (!evt.Resource.Name.EndsWith("-dapr-cli", StringComparison.Ordinal))
84	            {
85	                return;
86	            }
87	
88	            foreach (var probe in backendProbes)
89	            {
90	                await probe.WaitUntilReadyAsync(TimeSpan.FromMinutes(3), cancellationToken).ConfigureAwait(false);
91	            }
92	
93	            if (sidecarWaits.TryGetValue(evt.Resource.Name, out var subscriberSidecars))
94	            {
95	                var notifications = evt.Services.GetRequiredService<ResourceNotificationService>();
96	                foreach (var sidecar in subscriberSidecars)
97	                {
98	                    await notifications
99	                        .WaitForResourceAsync(sidecar, KnownResourceStates.Running, cancellationToken)
100	                        .ConfigureAwait(false);
101	                }
102	            }
103	        });
104	
105	        var resources = new Dictionary<string, IResourceBuilder<IResource>>(StringComparer.Ordinal);
106	        var waiters = new Dictionary<string, Action<IResourceBuilder<IResource>>>(StringComparer.Ordinal);
107	        var unresolved = new List<string>();
108	        foreach (var component in topology.Components)
109	        {
110	            // Each integration gets its own staged component set: its local files plus the
111	            // generated system overlay, at a stable inspectable path under obj/.
112	            var stagedPath = ComponentOverlay.Stage(builder.AppHostDirectory, component.Name, componentsPath);
113	
114	            var projectPath = ProjectConvention.Resolve(builder.AppHostDirectory, component.Name);
115	            if (!File.Exists(projectPath))
116	            {
117	                unresolved.Add($"{component.Name} (expected {projectPath})");
118	                continue;
119	            }
120	
121	            var project = builder.AddProject(component.Name, projectPath);
122	            if (component.Schedule is null)
123	            {
124	                // The endpoint makes Aspire allocate a port and inject ASPNETCORE_URLS (without it
125	                // every Kestrel binds the 5000 default) and gives the Dapr sidecar its app-port.
126	                // A scheduled component is a run-to-completion job that receives no inbound
127	                // delivery, so it gets neither.
128	                project = project.WithHttpEndpoint();
129	            }
130	            else
131	            {
132	                AddRunNowCommand(project, component.Name);
133	            }
134	
135	            Wire(project, component, stagedPath, configDir, backends);
136	            resources[component.Name] = project;
137	            waiters[component.Name] = dependency => project.WaitFor(dependency);
138	        }
139	
140	        RegisterDaprSidecarRecovery(builder, backendProbes);
141	        RegisterScheduler(builder, topology);
142	
143	        if (unresolved.Count > 0)
144	        {
145	            throw new InvalidOperationException(
146	                $"No project found for these components by folder convention: {string.Join(", ", unresolved)}. " +
147	                "Create the project next to the SystemHost.");
148	        }
149	
150	        // Subscribers start first, so a publisher's first message finds a registered
151	        // subscription. Nobody declares this: it is derived from who publishes and who
152	        // subscribes each topic. Publish/subscribe cycles cannot be ordered — skip entirely
153	        // rather than deadlock.
154	        var precedence = SubscriberPrecedence(topology);
155	        if (HasCycle(precedence))
156	        {
157	            Console.Error.WriteLine(
158	                "intropy: the topology's topics form a publish/subscribe cycle; " +
159	                "skipping subscriber-first startup ordering.");
160	            return;
161	        }
162	
163	        foreach (var (publisher, subscribers) in precedence)
164	        {
165	            if (!waiters.TryGetValue(publisher, out var wait))
166	            {
167	                continue;
168	            }
169	
170	            var materialized = subscribers.Where(resources.ContainsKey).ToArray();
171	            foreach (var subscriber in materialized)
172	            {
173	                wait(resources[subscriber]);
174	            }
175	
176	            if (materialized.Length > 0)
177	            {
178	                sidecarWaits[$"{publisher}-dapr-cli"] =
179	                    [.. materialized.Select(s => $"{s}-dapr-cli")];
180	            }
181	        }
182	    }
183	
184	    /// <summary>
185	    /// Registers the <see cref="ComponentScheduler"/> when any component declares a schedule.
186	    /// Keyed off <c>Schedule</c>, not the component kind — the scheduler is kind-blind.
187	    /// </summary>
188	    private static void RegisterScheduler(IDistributedApplicationBuilder builder, SystemTopology topology)
189	    {
190	        var scheduled = topology.Components
191	            .Where(c => c.Schedule is not null)
192	            .Select(c => new ScheduledComponent(c.Name, c.Schedule!))
193	            .ToArray();
194	        if (scheduled.Length == 0)
195	        {
196	            return;
197	        }
198	
199	        builder.Services.TryAddSingleton(TimeProvider.System);
200	        builder.Services.AddSingleton<IReadOnlyList<ScheduledComponent>>(scheduled);
201	        builder.Services.TryAddSingleton<IResourceLifecycle, AspireResourceLifecycle>();
202	        builder.Services.AddSingleton<ComponentScheduler>();
203	        builder.Services.AddHostedService(sp => sp.GetRequiredService<ComponentScheduler>());
204	    }
205	
206	    /// <summary>
207	    /// Registers recovery for every Dapr sidecar, including unscheduled components. The normal
208	    /// pre-start gate prevents the common race; recovery covers the remaining interval where a
209	    /// backend passes TCP readiness but daprd's component initialization still fails.
210	    /// </summary>
211	    private static void RegisterDaprSidecarRecovery(
212	        IDistributedApplicationBuilder builder, IReadOnlyList<TcpReadyHealthCheck> backendProbes)
213	    {
214	        builder.Services.TryAddSingleton<IResourceLifecycle, AspireResourceLifecycle>();
215	        builder.Services.AddSingleton<IResourceStateMonitor, AspireResourceStateMonitor>();
216	        builder.Services.AddSingleton<IBackendReadiness>(
217	            new BackendReadiness(backendProbes.Cast<IBackendReadiness>().ToArray()));
218	        builder.Services.AddSingleton<DaprSidecarRecovery>();
219	        builder.Services.AddHostedService(sp => sp.GetRequiredService<DaprSidecarRecovery>());
220	    }
221	
222	    /// <summary>
223	    /// A dashboard command that triggers a scheduled component immediately, through the same
224	    /// path as a cron tick — including the skip when the previous run is still in progress.
225	    /// </summary>
226	    private static void AddRunNowCommand(IResourceBuilder<ProjectResource> project, string componentName)
227	    {
228	        project.WithCommand(
229	            name: "intropy-run-now",
230	            displayName: "Run now",
231	            executeCommand: async context =>
232	            {
233	                var scheduler = context.ServiceProvider.GetRequiredService<ComponentScheduler>();
234	                await scheduler.TriggerAsync(componentName, "manual run", context.CancellationToken)
235	                    .ConfigureAwait(false);
236	                return CommandResults.Success();
237	            },
238	            commandOptions: new CommandOptions { IconName = "Play", IconVariant = IconVariant.Filled });
239	    }
240	
241	    /// <summary>
242	    /// Which components each publisher must wait for: every subscriber of every topic it
243	    /// publishes. Self-loops (a component consuming its own topic) are not orderable edges.
244	    /// </summary>
245	    private static Dictionary<string, HashSet<string>> SubscriberPrecedence(SystemTopology topology)
246	    {
247	        var precedence = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
248	        foreach (var topic in topology.Topics)
249	        {
250	            foreach (var publisher in topic.Publishers)
251	            {
252	                foreach (var subscriber in topic.Subscribers)
253	                {
254	                    if (string.Equals(publisher, subscriber, StringComparison.Ordinal))
255	                    {
256	                        continue;
257	                    }
258	
259	                    if (!precedence.TryGetValue(publisher, out var subscribers))
260	                    {
261	                        precedence[publisher] = subscribers = new HashSet<string>(StringComparer.Ordinal);
262	                    }
263	
264	                    subscribers.Add(subscriber);
265	                }
266	            }
267	        }
268	
269	        return precedence;
270	    }
271	
272	    private static bool HasCycle(Dictionary<string, HashSet<string>> edges)
273	    {
274	        var state = new Dictionary<string, int>(StringComparer.Ordinal); // 1 = visiting, 2 = done
275	
276	        bool Visit(string node)
277	        {
278	            if (state.TryGetValue(node, out var seen))
279	            {
280	                return seen == 1;
281	            }
282	
283	            state[node] = 1;
284	            if (edges.TryGetValue(node, out var next) && next.Any(Visit))
285	            {
286	                return true;
287	            }
288	
289	            state[node] = 2;
290	            return false;
291	        }
292	
293	        return edges.Keys.Any(Visit);
294	    }
295	
296	    private static void WithTcpReadiness(
297	        IDistributedApplicationBuilder builder, IResourceBuilder<ContainerResource> container, int port)
298	    {
299	        var key = $"{container.Resource.Name}-tcp-ready";
300	        builder.Services.AddHealthChecks().AddCheck(key, new TcpReadyHealthCheck("localhost", port));
301	        container.WithHealthCheck(key);
302	    }
303	
304	    private static void Wire<T>(
305	        IResourceBuilder<T> resource,
306	        ComponentModel component,
307	        string resourcesPath,
308	        string configDir,
309	        IReadOnlyList<IResourceBuilder<IResource>> backends)
310	        where T : IResourceWithEnvironment, IResourceWithWaitSupport
311	    {
312	        resource
313	            .WithDaprSidecar(sidecar =>
314	            {
315	                sidecar.WithOptions(new DaprSidecarOptions
316	                {
317	                    AppId = component.Name,
318	                    ResourcesPaths = [resourcesPath],
319	                });
320	                foreach (var backend in backends)
321	                {
322	                    sidecar.WaitFor(backend);
323	                }
324	            })
325	            .WithEnvironment("INTROPY__COMPONENT", component.Name)
326	            .WithEnvironment("INTROPY__CONFIG", Path.Combine(configDir, $"{component.Name}.intropy.json"));
327	
328	        foreach (var backend in backends)
329	        {
330	            resource.WaitFor(backend);
331	        }
332	    }
333	}
