1	using System.Text.Json;
2	using Intropy.Topology.Model;
3	
4	namespace Intropy.Topology.Test.Building;
5	
6	/// <summary>
7	/// The living spec: mirrors the SystemHost sample from the README and asserts the full
8	/// shape of the materialized model.
9	/// </summary>
10	public class EndToEndTests
11	{
12	    private static class ProductFlow
13	    {
14	        public static readonly TopicRef<RawEvent> Raw =
15	            TopicRef<RawEvent>.Define("product-distribution-pubsub", "product-raw");
16	    }
17	
18	    private static class PriceFlow
19	    {
20	        public static readonly TopicRef<RawEvent> Raw =
21	            TopicRef<RawEvent>.Define("product-distribution-pubsub", "price-raw");
