1	using Intropy.Topology.Model;
2	
3	namespace Intropy.Topology.Building;
4	
5	/// <summary>
6	/// Folds the builder declarations into the immutable model: components in declaration
7	/// order, resources deduplicated from usage and sorted for determinism. Materialization
8	/// never fails — structurally broken declarations still materialize (first-seen wins on
9	/// conflicts) so validation rules can inspect and report the full picture.
10	/// </summary>
11	internal static class TopologyMaterializer
12	{
13	    public static SystemTopology Materialize(SystemBuilder builder)
14	    {
15	        var components = new List<ComponentModel>();
16	        var topics = new Dictionary<(string PubSub, string Topic), TopicAccumulator>();
17	        var connectors = new Dictionary<string, ConnectorAccumulator>();
18	
19	        foreach (var component in builder.Components)
20	        {
21	            components.Add(MaterializeComponent(component, topics, connectors));
22	        }
23	
24	        return new SystemTopology
25	        {
26	            SystemName = builder.SystemName,
27	            Components = components,
28	            Topics = topics
29	                .OrderBy(t => t.Key.PubSub, StringComparer.Ordinal)
30	                .ThenBy(t => t.Key.Topic, StringComparer.Ordinal)
31	                .Select(t => new TopicResource
32	                {
33	                    PubSubName = t.Key.PubSub,
34	                    TopicName = t.Key.Topic,
35	                    ContractTypeName = t.Value.ContractTypeName,
36	                    Publishers = [.. t.Value.Publishers],
37	                    Subscribers = [.. t.Value.Subscribers],
38	                })
39	                .ToArray(),
40	            Connectors = connectors
41	                .OrderBy(c => c.Key, StringComparer.Ordinal)
42	                .Select(c => new ConnectorResource
43	                {
44	                    Name = c.Key,
45	                    Transport = c.Value.Transport,
46	                    Directions = [.. c.Value.Directions.Order()],
47	                    UsedBy = [.. c.Value.UsedBy],
48	                })
49	                .ToArray(),
50	        };
51	    }
52	
53	    private static ComponentModel MaterializeComponent(
54	        Component component,
55	        Dictionary<(string PubSub, string Topic), TopicAccumulator> topics,
56	        Dictionary<string, ConnectorAccumulator> connectors)
57	    {
58	        var subscribes = new List<TopicSubscription>();
59	        foreach (var topic in component.SubscribeCalls)
60	        {
61	            subscribes.Add(new TopicSubscription
62	            {
63	                PubSubName = topic.PubSubName,
64	                TopicName = topic.TopicName,
65	            });
66	            AccumulateTopic(topics, topic).Subscribers.Add(component.Name);
67	        }
68	
69	        var publishes = new List<PublishEdge>();
70	        foreach (var (port, topic) in component.PublishCalls)
71	        {
72	            publishes.Add(new PublishEdge
73	            {
74	                Port = port,
75	                PubSubName = topic.PubSubName,
76	                TopicName = topic.TopicName,
77	            });
78	            AccumulateTopic(topics, topic).Publishers.Add(component.Name);
79	        }
80	
81	        var connectorEdges = new List<ConnectorEdge>();
82	        var seenConnectorEdges = new HashSet<(string, ConnectorDirection)>();
83	        foreach (var (connector, direction) in component.ConnectorCalls)
84	        {
85	            AccumulateConnector(connectors, connector, direction).UsedBy.Add(component.Name);
86	            if (seenConnectorEdges.Add((connector.Name, direction)))
87	            {
88	                connectorEdges.Add(new ConnectorEdge { ConnectorName = connector.Name, Direction = direction });
89	            }
90	        }
91	
92	        return new ComponentModel
93	        {
94	            Name = component.Name,
95	            Kind = component.Kind,
96	            Schedule = component.ScheduleCall,
97	            Subscribes = subscribes,
98	            Publishes = publishes,
99	            Connectors = connectorEdges,
100	        };
101	    }
102	
103	    private static TopicAccumulator AccumulateTopic(
104	        Dictionary<(string PubSub, string Topic), TopicAccumulator> topics,
105	        TopicRef topic)
106	    {
107	        var key = (topic.PubSubName, topic.TopicName);
108	        if (!topics.TryGetValue(key, out var accumulator))
109	        {
110	            accumulator = new TopicAccumulator(topic.ContractType.FullName ?? topic.ContractType.Name);
111	            topics[key] = accumulator;
112	        }
113	
114	        return accumulator;
115	    }
116	
117	    private static ConnectorAccumulator AccumulateConnector(
118	        Dictionary<string, ConnectorAccumulator> connectors,
119	        ConnectorRef connector,
120	        ConnectorDirection direction)
121	    {
122	        if (!connectors.TryGetValue(connector.Name, out var accumulator))
123	        {
124	            // First-seen wins on identity; conflicting declarations are reported by validation.
125	            accumulator = new ConnectorAccumulator(connector.Transport);
126	            connectors[connector.Name] = accumulator;
127	        }
128	
129	        accumulator.Directions.Add(direction);
130	        return accumulator;
131	    }
132	
133	    private sealed class TopicAccumulator(string contractTypeName)
134	    {
135	        public string ContractTypeName { get; } = contractTypeName;
136	        public SortedSet<string> Publishers { get; } = new(StringComparer.Ordinal);
137	        public SortedSet<string> Subscribers { get; } = new(StringComparer.Ordinal);
138	    }
139	
140	    private sealed class ConnectorAccumulator(Transport transport)
141	    {
142	        public Transport Transport { get; } = transport;
143	        public HashSet<ConnectorDirection> Directions { get; } = [];
144	        public SortedSet<string> UsedBy { get; } = new(StringComparer.Ordinal);
145	    }
146	}
